<script setup lang="ts">import{ref}from'vue';import{api}from'../api';import type{Post}from'../types';import PostCard from'../components/PostCard.vue';const q=ref(''),items=ref<Post[]>([]),searched=ref(false);async function search(){items.value=await api('/search?q='+encodeURIComponent(q.value));searched.value=true}</script><template><section class="page-head"><p class="eyebrow">/ SEARCH</p><h1>搜索</h1><form class="search" @submit.prevent="search"><label class="sr-only" for="q">搜索文章</label><input id="q" v-model="q" required placeholder="搜索标题、摘要与正文…"><button>搜索</button></form></section><p v-if="searched&&!items.length" class="state">没有找到相关内容，换个关键词试试。</p><div class="grid"><PostCard v-for="p in items" :key="p.id" :post="p"/></div></template>
